TEMPLATE_FILE = "pl-intent-console-two-pass.mustache"
DEFAULT_ROW_LIMIT = 20
DEFAULT_MAX_RUNS = 10
MAX_GRADE_ROWS = 10000
# Model calls per generation: one parses the plan into typed steps, one compiles
# the validated steps to SQL.
STAGE_COUNT = 2
# SQL generation goes through the course's English-to-SQL proxy (see proxy/README.md),
# which holds the OpenAI key and enforces the generation limits.
